#!/usr/bin/env python3
"""deny_generated_edit.py — PreToolUse(Edit|Write|MultiEdit|NotebookEdit|Bash): no hand edit of a GENERATED file.

Earned by: lettuce `tools/hooks/deny_generated_edit.py` — a generated file in git is a CLAIM, and a hand edit makes
it false until the next regeneration silently reverts it; matching the bare word GENERATED hit 489 files (hand files
included) and forbade the checker's own repair, so the declaration SENTENCE (tools/map/_common.GEN_DECL, first three
lines) is required; and refusing `git checkout --ours <generated>` mid-conflict was a stuck gate with no release.
Release (CA-08): restoring recorded content is exempt — `git checkout|restore` from a named rev, `--ours`/`--theirs`,
or `--source`; and the real fix is always `python3 <generator> --write` (or `python3 tools/map/map_check.py --write`).
The ONLY generated-edit guard in the kit (GOV 6.4 c). Paths under a held lane are left to deny_upstream_write.
Deny shape: exit 2 with the reason on stderr (the harness feeds stderr to the model). Exit 0 otherwise, fail open.
"""
import json
import re
import shlex
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import _common as C  # noqa: E402

FILE_TOOLS = {"Edit", "Write", "MultiEdit", "NotebookEdit"}
RESTORE = re.compile(r"^\s*git\s+(?:-C\s+\S+\s+)?(?:checkout|restore)\b")


def generator_of(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            head = "".join(fh.readline() for _ in range(3))
    except OSError:
        return None
    if not C.declares_generated(head):
        return None
    m = re.search(r'GENERATED by (\S+)|"_generated_by"\s*:\s*"([^"]+)"', head)
    return (m.group(1) or m.group(2)) if m else "its generator"


def bash_targets(cmd):
    """Files a shell command would write: redirects, tee, sed -i. Restores from a recorded source are exempt."""
    out = []
    for seg in re.split(r"&&|\|\||;|\n", cmd):
        if RESTORE.match(seg):
            continue
        out += re.findall(r"(?<![<>&\d])>>?\s*([^\s;&|<>]+)", seg)
        try:
            toks = shlex.split(seg)
        except ValueError:
            toks = seg.split()
        for i, tk in enumerate(toks):
            if tk == "tee":
                out += [x for x in toks[i + 1:] if not x.startswith("-") and x not in ("|",)]
            if tk == "sed" and any(x.startswith("-i") or x == "--in-place" for x in toks[i + 1:]):
                out += [x for x in toks[i + 1:][-1:] if not x.startswith("-")]
    return [t.strip("'\"") for t in out if t and not t.startswith("/dev/")]


def decide(payload, root):
    tool = payload.get("tool_name") or ""
    ti = payload.get("tool_input") or {}
    if tool in FILE_TOOLS:
        paths = [ti.get("file_path") or ti.get("notebook_path") or ""]
    elif tool == "Bash":
        paths = bash_targets(ti.get("command") or "")
    else:
        return None
    cfg = C.domain_cfg(root)
    for p in paths:
        if not p:
            continue
        ap = Path(p) if Path(p).is_absolute() else Path(root) / p
        try:
            rel = ap.resolve().relative_to(Path(root).resolve()).as_posix()
        except ValueError:
            continue
        if C.classify(rel, cfg) != "domain" or not ap.is_file():
            continue
        gen = generator_of(ap)
        if gen:
            return ("GENERATED by %s: %s is generated; edit its source and run python3 %s --write "
                    "(or python3 tools/map/map_check.py --write). Restore with git checkout <rev> -- %s." % (gen, rel, gen, rel))
    return None


def selftest():
    import tempfile
    ok = True
    with tempfile.TemporaryDirectory() as t:
        Path(t, "map").mkdir()
        Path(t, "map", "SOLUTIONS.md").write_text("<!-- GENERATED by tools/map/gen_solutions.py -->\n# x\n")
        Path(t, "map", "atlas.json").write_text('{\n "_generated_by": "tools/map/gen_atlas.py",\n "x": 1\n}\n')
        Path(t, "tools").mkdir()
        Path(t, "tools", "hand.py").write_text('"""This module writes the generated files."""\n')
        Path(t, "upstream", "a~b").mkdir(parents=True)
        Path(t, "upstream", "a~b", "G.md").write_text("<!-- GENERATED by x -->\n")
        cases = [("Write", {"file_path": "map/SOLUTIONS.md"}, True), ("Edit", {"file_path": str(Path(t, "map", "atlas.json"))}, True),
                 ("Edit", {"file_path": "tools/hand.py"}, False), ("Write", {"file_path": "tools/new.py"}, False),
                 ("Bash", {"command": "git checkout HEAD -- map/atlas.json"}, False),
                 ("Bash", {"command": "git checkout --ours map/atlas.json && git add map/atlas.json"}, False),
                 ("Bash", {"command": "echo x > map/atlas.json"}, True), ("Bash", {"command": "cat a | tee -a map/SOLUTIONS.md"}, True),
                 ("Bash", {"command": "sed -i 's/a/b/' map/SOLUTIONS.md"}, True), ("Bash", {"command": "echo x > /dev/null"}, False),
                 ("Write", {"file_path": "upstream/a~b/G.md"}, False)]
        for tool, ti, deny in cases:
            got = decide({"tool_name": tool, "tool_input": ti}, t) is not None
            if got != deny:
                ok = False
                print("FAIL", tool, ti, "expected", "deny" if deny else "allow")
    print("selftest OK" if ok else "selftest FAILED")
    return 0 if ok else 1


def main():
    if "--selftest" in sys.argv:
        return selftest()
    try:
        payload = json.loads(sys.stdin.read() or "{}")
        reason = decide(payload, C.ROOT)
    except Exception:  # noqa: BLE001 -- fail open
        return 0
    if reason:
        sys.stderr.write(reason + "\n")
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
